class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict

    def add_edge(self, vertex, edge):
        if vertex in self.graph_dict:
            self.graph_dict[vertex].append(edge)
        else:
            self.graph_dict[vertex] = [edge]

    def dfs(self, start_vertex, target, path=None):
        if path is None:
            path = []
        path = path + [start_vertex]

        if start_vertex == target:
            return path

        if start_vertex not in self.graph_dict:
            return None

        for vertex in self.graph_dict[start_vertex]:
            if vertex not in path:
                new_path = self.dfs(vertex, target, path)
                if new_path:
                    return new_path

        return None

