class Graph:
    def __init__(self, vertices):
        self.V = vertices  # Number of vertices
        self.graph = {}  # Dictionary to represent the graph

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def is_safe(self, v, colour, c):
        for i in self.graph[v]:
            if colour[i] == c:
                return False
        return True

    def DFSUtil(self, v, colour):
        colour[v] = 1  # Mark the current node as visited

        for i in self.graph[v]:
            if colour[i] == 0:  # If an adjacent is not visited
                if not self.is_safe(v, colour, 3 - colour[v]):
                    return False
                self.DFSUtil(i, colour)
        colour[v] = 2  # Mark the current node as visited

    def is_bipartite(self):
        colour = [0] * self.V  # Initialize colors for all vertices as 0 (unvisited)
        for i in range(self.V):
            if colour[i] == 0 and not self.DFSUtil(i, colour):
                return False
        return True

# Example usage:
