        'D': ['B'],
        'E': ['B', 'F'],
        'F': ['C', 'E']
    }

    start_node = 'A'
    end_node = 'F'

    paths = dfs(graph, start_node, end_node)

    if paths:
        print(f"Path(s) from {start_node} to {end_node}:")
        for path in paths:
            print(path)
    else:
