Certainly! Path search algorithms are fundamental in graph theory and are used to find the shortest path or a valid sequence of steps between two points in a graph. One of the most popular algorithms for this purpose is Dijkstra's algorithm, which is used for graphs with non-negative edge weights.

Here's a Python implementation of Dijkstra's algorithm:

```python
import heapq

def dijkstra(graph, start):
    # Priority queue (min-heap) to store the nodes to be visited
    priority_queue = [(0, start)]  # (distance, node)
    visited = set()  # Set to keep track of visited nodes
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

# Example usage:
if __name__ == "__main__":
    # Define a graph
    graph = {
        'A': {'B': 1, 'C': 4},
        'B': {'A': 1, 'C': 2, 'D': 5},
        'C': {'A': 4, 'B': 2, 'D': 1},
        'D': {'B': 5, 'C': 1}
    }

    start_node = 'A'
    shortest_distances = dijkstra(graph, start_node)

    print(f"Shortest distances from {start_node}:")
    for node, distance in shortest_distances.items():
        print(f"Node {node}: {distance}")
```

