class Graph:
    def __init__(self):
        self.graph = {}

    def add_node(self, node):
        if node not in self.graph:
            self.graph[node] = []

    def add_edge(self, start_node, end_node):
        if start_node in self.graph and end_node in self.graph:
            self.graph[start_node].append(end_node)
        else:
            raise ValueError("One or both nodes do not exist in the graph")

    def dfs(self, start_node, goal_node):
        visited = set()
        stack = [start_node]

        while stack:
            current_node = stack.pop()
            if current_node == goal_node:
                return True, current_node
            if current_node not in visited:
                visited.add(current_node)
                if current_node in self.graph:
                    stack.extend(self.graph[current_node] - visited)
        return False, None

