import heapq

class Node:
    def __init__(self, position, parent=None):
        self.position = position
        self.parent = parent
        self.g = 0  # Distance from start node
        self.h = 0  # Distance to the goal node
        self.f = 0  # Estimated total path cost

    def __lt__(self, other):
        return self.f < other.f

def heuristic(node, goal_node):
    # Manhattan distance as heuristic for simplicity
    return abs(node.position[0] - goal_node.position[0]) + abs(node.position[1] - goal_node.position[1])

def astar_search(graph, start, goal):
    open_list = []
    start_node = Node(start)
    heapq.heappush(open_list, start_node)

    while open_list:
        current_node = heapq.heappop(open_list)

        if current_node.position == goal:
            path = []
            while current_node:
                path.append(current_node.position)
                current_node = current_node.parent
            return path[::-1]  # Return reversed path

        for next_position in graph.get(current_node.position, []):
            next_node = Node(next_position, current_node)
            next_node.g = current_node.g + 1
            next_node.h = heuristic(next_node, goal)
            next_node.f = next_node.g + next_node.h

            if next_node not in graph:
                graph[next_node.position] = []
            if next_node not in open_list:
                heapq.heappush(open_list, next_node)
            else:
                if next_node.f < open_list[open_list.index(next_node)].f:
                    open_list[open_list.index(next_node)] = next_node
    return None

